using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Drawing.Imaging;using System.Reflection;using System.Web.Script.Serialization;using System.Windows.Forms;using PaperInbox;
public static class LayoutChecks {
 static List<object> checks=new List<object>();static void Check(string name,bool ok){checks.Add(new{name,passed=ok});if(!ok)throw new Exception(name);}
 static T Field<T>(object obj,string n){return (T)obj.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(obj);}
 static IEnumerable<Control> All(Control c){foreach(Control x in c.Controls){yield return x;foreach(Control y in All(x))yield return y;}}
 static void Inputs(ReviewForm f,string size){foreach(string n in new[]{"generationMode","year","type","subjects","collections","tags"}){Control c=Field<Control>(f,n);Check(size+"："+n+"输入内容不超出容器",c.Parent.ClientRectangle.Contains(c.Bounds));Check(size+"："+n+"外框不被上一层裁切",c.Parent.Parent.ClientRectangle.Contains(c.Parent.Bounds));}var approve=All(f).OfType<Button>().Single(b=>b.Text=="确认放入 Zotero");Check(size+"：确认按钮保持在窗口内",f.RectangleToScreen(f.ClientRectangle).Contains(approve.RectangleToScreen(approve.ClientRectangle)));}
 static void Corner(ReviewForm f,string path){using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));Control field=Field<Control>(f,"doi").Parent;foreach(var p in new[]{Point.Empty,new Point(field.Width-1,0),new Point(0,field.Height-1),new Point(field.Width-1,field.Height-1)}){Point offset=f.PointToClient(field.PointToScreen(p));Color c=bitmap.GetPixel(offset.X,offset.Y);Check("圆角外部无方形黑底："+p,c.R>200&&c.G>200&&c.B>200);}bitmap.Save(path,ImageFormat.Png);}}
 [STAThread]public static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=args[0];Directory.CreateDirectory(root);try{
  var a=TopicTests.CuO();MaterialThemes.Upgrade(a);a.year="2026";using(var f=new ReviewForm(a)){AiTests.Render(f,Path.Combine(root,"review-normal.png"));Inputs(f,"标准尺寸");Corner(f,Path.Combine(root,"review-normal.png"));f.Size=new Size(840,640);Application.DoEvents();AiTests.Render(f,Path.Combine(root,"review-small.png"));Inputs(f,"窄窗口");var scroll=All(f).OfType<Panel>().First(p=>p.AutoScroll);Check("窄窗口内容可纵向滚动",scroll.VerticalScroll.Visible&&scroll.AutoScrollMinSize.Height>scroll.ClientSize.Height);Check("窄窗口无需横向滚动",!scroll.HorizontalScroll.Visible);Field<Control>(f,"collections").Focus();scroll.ScrollControlIntoView(Field<Control>(f,"collections"));Application.DoEvents();AiTests.Render(f,Path.Combine(root,"review-small-categories.png"));f.Close();}
  a=TopicTests.CuO();MaterialThemes.Upgrade(a);using(var f=new ReviewForm(a)){AiTests.Render(f,Path.Combine(root,"scale-initial.png"));f.Scale(new SizeF(1.5f,1.5f));f.Size=new Size(1560,1050);Application.DoEvents();AiTests.Render(f,Path.Combine(root,"review-150-percent.png"));Inputs(f,"150%布局缩放");f.Close();}
  var store=new StateStore(Path.Combine(root,"api-state"));using(var api=new ApiSettingsForm(store)){AiTests.Render(api,Path.Combine(root,"api-normal.png"));foreach(var button in All(api).OfType<Button>().Where(b=>b.Text.StartsWith("高级连接设置")).ToArray())button.PerformClick();Application.DoEvents();AiTests.Render(api,Path.Combine(root,"api-advanced.png"));foreach(var n in new[]{"chars","pages","protocol","endpoint"}){Control c=Field<Control>(api,n);Check("API设置："+n+"不超出输入框",c.Parent.ClientRectangle.Contains(c.Bounds));Check("API设置："+n+"外框不被裁切",c.Parent.Parent.ClientRectangle.Contains(c.Parent.Bounds));}api.Close();}
  File.WriteAllText(Path.Combine(root,"results.json"),new JavaScriptSerializer().Serialize(new{success=true,checks}));return 0;
 }catch(Exception e){File.WriteAllText(Path.Combine(root,"results.json"),new JavaScriptSerializer().Serialize(new{success=false,checks,error=e.ToString()}));return 1;}}
}
